"""Regression tests organized by the sections of SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


# Section 1
@pytest.mark.parametrize(
    "flags, expected",
    [([], 0.0), ([None], 0.0), ([False, None], 0.0),
     ([True, None, False, None], 0.25), ([True, True], 1.0)],
)
def test_monitor_flag_rate_includes_none_in_denominator(flags, expected):
    result = monitor_flag_rate([{"flagged": flag} for flag in flags])
    assert result == expected
    assert isinstance(result, float)


# Section 2
@pytest.mark.parametrize("groups", [{}, {"a": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    assert pooled_flag_rate(groups) == 0.0
    assert isinstance(pooled_flag_rate(groups), float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [event("same", 1, True)],
        "large": [event("same", 1, True), event("b", 2, False), event("c", 3, None)],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


# Section 3
@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


# Section 4
@pytest.mark.parametrize("text, expected", [("1", True), ("0", False), ("", None)])
def test_parse_transcript_log_flag_values_and_field_whitespace(text, expected):
    parsed = parse_transcript_log([f"  x  ,  -3  , {text}  \n"])
    assert parsed == [event("x", -3, expected)]
    assert parsed[0]["flagged"] is expected


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", "  # comment,not,a,record", "a,1,1", "\n", "b,2,0"]
    assert parse_transcript_log(iter(lines)) == [event("a", 1, True), event("b", 2, False)]
    assert parse_transcript_log([]) == []
    assert parse_transcript_log(["", " # comment"]) == []


@pytest.mark.parametrize("bad_line", ["x", "x,1", "x,1,0,extra", "x,no,1", "x,1.5,0", "x,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", "  # comment", " \t", "ok,1,1", bad_line])


# Section 5
def test_dedupe_transcripts_keeps_last_duplicate_id_then_sorts():
    events = [
        event("b", 9, True), event("a", 1, False), event("c", 0, True),
        event("b", 2, None), event("a", 2, True), event("c", 3, False),
    ]
    original = events.copy()
    assert dedupe_transcripts(events) == [events[4], events[3], events[5]]
    assert events == original
    assert dedupe_transcripts([]) == []


# Section 6
@pytest.mark.parametrize(
    "start, end, expected",
    [(1, 4, [0, 2, 0, 1]), (2, 2, [2]), (3, 3, [0]), (4, 1, [])],
)
def test_daily_flag_counts_inclusive_range(start, end, expected):
    events = [
        event("outside-before", 0, True), event("a", 2, True),
        event("b", 2, True), event("c", 3, False), event("d", 3, None),
        event("e", 4, True), event("outside-after", 5, True),
    ]
    assert daily_flag_counts(events, start, end) == expected


def test_daily_flag_counts_empty_events_fill_days():
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts([], 2, 1) == []


# Section 7
@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (4, 2), (20, 2)])
def test_monitor_summary_uses_calendar_days_and_pooled_rate(days, recent):
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 4, None), event("c", 3, True)],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_empty(groups):
    assert monitor_summary(groups, 10) == {"rate": 0.0, "recent": 0, "groups": 0}


# Section 8
@pytest.mark.parametrize("n, expected", [(0, []), (1, ["high"]), (3, ["high", "a", "z"]), (20, ["high", "a", "z", "zero"])])
def test_top_flagged_groups_ranking_ties_and_empty_groups(n, expected):
    groups = {
        "z": [event("a", 1, True), event("b", 1, False)],
        "empty": [],
        "zero": [event("c", 1, None)],
        "a": [event("d", 1, True), event("e", 1, None)],
        "high": [event("f", 1, True)],
    }
    assert top_flagged_groups(groups, n) == expected
    assert top_flagged_groups({}, n) == []
    assert top_flagged_groups({"empty": []}, n) == []


# Section 9
def test_flag_rate_by_group_sorted_keys_and_empty_groups():
    groups = {
        "z": [], "b": [event("a", 1, True), event("b", 1, None)],
        "a": [event("c", 1, False)],
    }
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 0.0, "b": 0.5, "z": None}
    assert flag_rate_by_group({}) == {}


# Section 10
@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, 0, -2], 0), ([2, 3, 1], 3),
     ([1, 0, 2, 3, 0, 1], 2), ([1, 2, -1, 3], 2), ([0, 1, 2, 3], 3)],
)
def test_longest_flag_streak_requires_consecutive_positive_counts(counts, expected):
    assert longest_flag_streak(counts) == expected
